import { MAX_STACK_SIZE } from "@/lib/game/config";
import { ARMOR_SLOTS, createEmptySlot, createSlot, ITEM_DEF_BY_ID } from "@/lib/game/items";
import type { EquippedArmor, InventorySlot, Recipe } from "@/lib/game/types";

/**
 * Pure inventory slot algebra. Every mutation returns a NEW slots array, or
 * null when the operation does not apply — callers keep the previous array on
 * null, so reference equality doubles as a change signal for React.
 */

export function cloneSlots(slots: InventorySlot[]): InventorySlot[] {
  return slots.map((slot) => ({ ...slot }));
}

export function countsById(slots: InventorySlot[]): Map<string, number> {
  const byId = new Map<string, number>();
  for (const slot of slots) {
    if (!slot.id || slot.count <= 0) continue;
    byId.set(slot.id, (byId.get(slot.id) ?? 0) + slot.count);
  }
  return byId;
}

/**
 * Adds (delta > 0) or removes (delta < 0) items. Removal is all-or-nothing:
 * if the inventory holds fewer than |delta|, nothing is removed and null is
 * returned. Addition fills existing stacks, then empty slots; whatever does
 * not fit is dropped (a full inventory loses surplus block drops).
 */
export function adjustSlotCount(slots: InventorySlot[], slotId: string, delta: number, preferredIndex?: number): InventorySlot[] | null {
  if (!slotId || delta === 0) return null;
  const next = cloneSlots(slots);
  let remaining = Math.abs(delta);

  if (delta < 0) {
    const consumeFromIndex = (index: number) => {
      if (remaining <= 0) return;
      if (index < 0 || index >= next.length) return;
      const slot = next[index];
      if (slot.id !== slotId || slot.count <= 0) return;
      const take = Math.min(remaining, slot.count);
      slot.count -= take;
      remaining -= take;
      if (slot.count <= 0) next[index] = createEmptySlot();
    };

    if (typeof preferredIndex === "number") consumeFromIndex(preferredIndex);
    for (let i = 0; i < next.length && remaining > 0; i += 1) consumeFromIndex(i);
    if (remaining > 0) return null;
    return next;
  }

  if (!ITEM_DEF_BY_ID[slotId]) return null;

  const fillIndex = (index: number) => {
    if (remaining <= 0) return;
    if (index < 0 || index >= next.length) return;
    const slot = next[index];
    if (slot.id !== slotId || slot.count >= MAX_STACK_SIZE) return;
    const add = Math.min(remaining, MAX_STACK_SIZE - slot.count);
    slot.count += add;
    remaining -= add;
  };

  if (typeof preferredIndex === "number") fillIndex(preferredIndex);
  for (let i = 0; i < next.length && remaining > 0; i += 1) fillIndex(i);
  for (let i = 0; i < next.length && remaining > 0; i += 1) {
    if (next[i].id !== null || next[i].count !== 0) continue;
    const add = Math.min(remaining, MAX_STACK_SIZE);
    next[i] = createSlot(slotId, add);
    remaining -= add;
  }
  return next;
}

/** Wears the tool/weapon at `index` by `amount`; the slot empties at zero durability. */
export function consumeToolDurability(slots: InventorySlot[], index: number, amount = 1): InventorySlot[] | null {
  if (amount <= 0) return null;
  if (index < 0 || index >= slots.length) return null;
  const next = cloneSlots(slots);
  const slot = next[index];
  if ((slot.kind !== "tool" && slot.kind !== "weapon") || !slot.id || slot.count <= 0 || !slot.maxDurability) return null;
  const nextDurability = (slot.durability ?? slot.maxDurability) - amount;
  if (nextDurability <= 0) {
    next[index] = createEmptySlot();
    return next;
  }
  slot.durability = nextDurability;
  return next;
}

/** Wears every equipped armor piece by `amount`; broken pieces disappear. */
export function consumeEquippedArmorDurability(slots: InventorySlot[], equipped: EquippedArmor, amount = 1): InventorySlot[] | null {
  if (amount <= 0) return null;
  const next = cloneSlots(slots);
  let changed = false;
  for (const armorSlot of ARMOR_SLOTS) {
    const equippedId = equipped[armorSlot];
    if (!equippedId) continue;
    const idx = next.findIndex((slot) => slot.id === equippedId && slot.kind === "armor" && slot.count > 0);
    if (idx < 0) continue;
    const slot = next[idx];
    if (!slot.maxDurability) continue;
    const nextDurability = (slot.durability ?? slot.maxDurability) - amount;
    if (nextDurability <= 0) next[idx] = createEmptySlot();
    else slot.durability = nextDurability;
    changed = true;
  }
  return changed ? next : null;
}

export function canCraft(slots: InventorySlot[], recipe: Recipe): boolean {
  const byId = countsById(slots);
  const hasCost = recipe.cost.every((cost) => (byId.get(cost.slotId) ?? 0) >= cost.count);
  if (!hasCost) return false;

  let freeForResult = 0;
  for (const slot of slots) {
    if (slot.id === recipe.result.slotId) freeForResult += MAX_STACK_SIZE - slot.count;
    if (slot.id === null && slot.count === 0) freeForResult += MAX_STACK_SIZE;
  }
  return freeForResult >= recipe.result.count;
}

/**
 * Consumes the recipe cost and adds the result. Returns null unless the cost
 * is affordable AND the result fits — crafting never silently destroys the
 * overflow (this previously could happen when the inventory was full).
 */
export function craft(slots: InventorySlot[], recipe: Recipe): InventorySlot[] | null {
  if (!ITEM_DEF_BY_ID[recipe.result.slotId]) return null;
  if (!canCraft(slots, recipe)) return null;

  const next = cloneSlots(slots);
  for (const cost of recipe.cost) {
    let remaining = cost.count;
    for (let i = 0; i < next.length && remaining > 0; i += 1) {
      if (next[i].id !== cost.slotId || next[i].count <= 0) continue;
      const take = Math.min(remaining, next[i].count);
      next[i].count -= take;
      remaining -= take;
      if (next[i].count <= 0) next[i] = createEmptySlot();
    }
  }

  let remaining = recipe.result.count;
  for (let i = 0; i < next.length && remaining > 0; i += 1) {
    if (next[i].id !== recipe.result.slotId || next[i].count >= MAX_STACK_SIZE) continue;
    const add = Math.min(remaining, MAX_STACK_SIZE - next[i].count);
    next[i].count += add;
    remaining -= add;
  }
  for (let i = 0; i < next.length && remaining > 0; i += 1) {
    if (next[i].id !== null || next[i].count !== 0) continue;
    const add = Math.min(remaining, MAX_STACK_SIZE);
    next[i] = createSlot(recipe.result.slotId, add);
    remaining -= add;
  }
  return next;
}

export function swapSlots(slots: InventorySlot[], fromIndex: number, toIndex: number): InventorySlot[] | null {
  if (fromIndex === toIndex) return null;
  if (fromIndex < 0 || toIndex < 0 || fromIndex >= slots.length || toIndex >= slots.length) return null;
  const next = cloneSlots(slots);
  const temp = next[fromIndex];
  next[fromIndex] = next[toIndex];
  next[toIndex] = temp;
  return next;
}

/** Toggles the armor piece at `index` in its armor slot. */
export function toggleEquipArmor(slots: InventorySlot[], equipped: EquippedArmor, index: number): EquippedArmor | null {
  if (index < 0 || index >= slots.length) return null;
  const slot = slots[index];
  if (slot.kind !== "armor" || !slot.id || !slot.armorSlot || slot.count <= 0) return null;
  const next = { ...equipped };
  next[slot.armorSlot] = equipped[slot.armorSlot] === slot.id ? null : slot.id;
  return next;
}

/** Unequips armor pieces no longer present in the inventory (broken or dropped). */
export function unequipMissingArmor(slots: InventorySlot[], equipped: EquippedArmor): EquippedArmor | null {
  let changed = false;
  const next = { ...equipped };
  for (const armorSlot of ARMOR_SLOTS) {
    const equippedId = next[armorSlot];
    if (!equippedId) continue;
    const stillOwned = slots.some((slot) => slot.id === equippedId && slot.count > 0);
    if (stillOwned) continue;
    next[armorSlot] = null;
    changed = true;
  }
  return changed ? next : null;
}

/** Total defense points from equipped, still-owned armor (drives the HUD armor bar). */
export function equippedDefense(slots: InventorySlot[], equipped: EquippedArmor): number {
  let defense = 0;
  for (const armorSlot of ARMOR_SLOTS) {
    const equippedId = equipped[armorSlot];
    if (!equippedId) continue;
    const def = ITEM_DEF_BY_ID[equippedId];
    if (!def || def.kind !== "armor" || def.armorSlot !== armorSlot) continue;
    const hasOwnedPiece = slots.some((slot) => slot.id === equippedId && slot.count > 0);
    if (!hasOwnedPiece) continue;
    defense += def.defense ?? 0;
  }
  return defense;
}

/** Damage reduction from equipped, still-owned armor: 5% per defense point, capped at 75%. */
export function armorReduction(slots: InventorySlot[], equipped: EquippedArmor): number {
  return Math.min(0.75, equippedDefense(slots, equipped) * 0.05);
}

import { describe, expect, test } from "bun:test";
import { INVENTORY_SLOTS, MAX_STACK_SIZE } from "@/lib/game/config";
import { createEmptyArmorEquipment, createEmptySlot, createSlot } from "@/lib/game/items";
import { RECIPES } from "@/lib/game/recipes";
import {
  adjustSlotCount,
  armorReduction,
  equippedDefense,
  canCraft,
  consumeEquippedArmorDurability,
  consumeToolDurability,
  countsById,
  craft,
  swapSlots,
  toggleEquipArmor,
  unequipMissingArmor
} from "@/lib/game/inventory";
import type { InventorySlot } from "@/lib/game/types";

function makeSlots(...items: Array<[string, number] | null>): InventorySlot[] {
  const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
  items.forEach((item, i) => {
    if (item) slots[i] = createSlot(item[0], item[1]);
  });
  return slots;
}

const planksRecipe = RECIPES.find((recipe) => recipe.id === "planks")!; // 2 wood -> 4 planks
const brickRecipe = RECIPES.find((recipe) => recipe.id === "brick")!; // 2 dirt + 2 stone -> 2 brick

describe("countsById", () => {
  test("sums across stacks and skips empties", () => {
    const slots = makeSlots(["dirt", 30], ["stone", 5], null, ["dirt", 12]);
    const byId = countsById(slots);
    expect(byId.get("dirt")).toBe(42);
    expect(byId.get("stone")).toBe(5);
    expect(byId.has("")).toBe(false);
  });
});

describe("adjustSlotCount", () => {
  test("removal drains the preferred slot first, then scans", () => {
    const slots = makeSlots(["dirt", 10], ["dirt", 10]);
    const next = adjustSlotCount(slots, "dirt", -12, 1)!;
    expect(next[1].count).toBe(0);
    expect(next[1].id).toBeNull();
    expect(next[0].count).toBe(8);
  });

  test("removal is all-or-nothing when short", () => {
    const slots = makeSlots(["dirt", 5]);
    expect(adjustSlotCount(slots, "dirt", -6)).toBeNull();
    expect(slots[0].count).toBe(5); // input untouched
  });

  test("addition fills existing stacks then empty slots", () => {
    const slots = makeSlots(["dirt", MAX_STACK_SIZE - 2]);
    const next = adjustSlotCount(slots, "dirt", 5)!;
    expect(next[0].count).toBe(MAX_STACK_SIZE);
    expect(next[1].id).toBe("dirt");
    expect(next[1].count).toBe(3);
  });

  test("addition drops surplus when the inventory is full", () => {
    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createSlot("stone", MAX_STACK_SIZE));
    const next = adjustSlotCount(slots, "dirt", 10)!;
    expect(countsById(next).get("dirt")).toBeUndefined();
  });

  test("unknown items and zero deltas are no-ops", () => {
    const slots = makeSlots(["dirt", 5]);
    expect(adjustSlotCount(slots, "no_such_item", 3)).toBeNull();
    expect(adjustSlotCount(slots, "dirt", 0)).toBeNull();
  });

  test("never mutates the input array", () => {
    const slots = makeSlots(["dirt", 10]);
    adjustSlotCount(slots, "dirt", -4);
    adjustSlotCount(slots, "dirt", 4);
    expect(slots[0].count).toBe(10);
  });
});

describe("durability", () => {
  test("tool wears down and breaks at zero", () => {
    let slots = makeSlots(["wood_pickaxe", 1]);
    const max = slots[0].maxDurability!;
    slots = consumeToolDurability(slots, 0, max - 1)!;
    expect(slots[0].durability).toBe(1);
    slots = consumeToolDurability(slots, 0, 1)!;
    expect(slots[0].id).toBeNull(); // broke
  });

  test("blocks have no durability to consume", () => {
    const slots = makeSlots(["dirt", 5]);
    expect(consumeToolDurability(slots, 0, 1)).toBeNull();
  });

  test("equipped armor wears together; broken pieces vanish", () => {
    let slots = makeSlots(["helmet", 1], ["boots", 1]);
    const equipped = { ...createEmptyArmorEquipment(), helmet: "helmet", boots: "boots" };
    slots = consumeEquippedArmorDurability(slots, equipped, slots[1].maxDurability! - 1)!;
    expect(slots[0].durability).toBe(slots[0].maxDurability! - (slots[1].maxDurability! - 1));
    expect(slots[1].durability).toBe(1);
    slots = consumeEquippedArmorDurability(slots, equipped, 1)!;
    expect(slots[1].id).toBeNull(); // boots broke, helmet survives
    expect(slots[0].id).toBe("helmet");
  });

  test("nothing equipped is a no-op", () => {
    const slots = makeSlots(["helmet", 1]);
    expect(consumeEquippedArmorDurability(slots, createEmptyArmorEquipment(), 1)).toBeNull();
  });
});

describe("crafting", () => {
  test("canCraft needs both the cost and room for the result", () => {
    expect(canCraft(makeSlots(["wood", 2]), planksRecipe)).toBe(true);
    expect(canCraft(makeSlots(["wood", 1]), planksRecipe)).toBe(false);

    // Cost present but zero room for the result.
    const full = Array.from({ length: INVENTORY_SLOTS }, () => createSlot("stone", MAX_STACK_SIZE));
    full[0] = createSlot("wood", MAX_STACK_SIZE);
    expect(canCraft(full, planksRecipe)).toBe(false);
  });

  test("craft consumes the cost and adds the result", () => {
    const next = craft(makeSlots(["dirt", 10], ["stone", 10]), brickRecipe)!;
    const byId = countsById(next);
    expect(byId.get("dirt")).toBe(8);
    expect(byId.get("stone")).toBe(8);
    expect(byId.get("brick")).toBe(2);
  });

  test("craft refuses instead of destroying overflow when the inventory is full", () => {
    const full = Array.from({ length: INVENTORY_SLOTS }, () => createSlot("stone", MAX_STACK_SIZE));
    full[0] = createSlot("wood", MAX_STACK_SIZE);
    expect(craft(full, planksRecipe)).toBeNull(); // cost NOT consumed
  });

  test("crafted gear gets fresh durability", () => {
    const next = craft(makeSlots(["planks", 4], ["wood", 4]), RECIPES.find((recipe) => recipe.id === "wood_pickaxe")!)!;
    const pick = next.find((slot) => slot.id === "wood_pickaxe")!;
    expect(pick.durability).toBe(pick.maxDurability);
  });
});

describe("swap and armor", () => {
  test("swapSlots exchanges two slots and rejects bad indices", () => {
    const slots = makeSlots(["dirt", 5], ["stone", 7]);
    const next = swapSlots(slots, 0, 1)!;
    expect(next[0].id).toBe("stone");
    expect(next[1].id).toBe("dirt");
    expect(swapSlots(slots, 0, 0)).toBeNull();
    expect(swapSlots(slots, 0, INVENTORY_SLOTS)).toBeNull();
  });

  test("toggleEquipArmor equips then unequips", () => {
    const slots = makeSlots(["helmet", 1]);
    const empty = createEmptyArmorEquipment();
    const equipped = toggleEquipArmor(slots, empty, 0)!;
    expect(equipped.helmet).toBe("helmet");
    const unequipped = toggleEquipArmor(slots, equipped, 0)!;
    expect(unequipped.helmet).toBeNull();
    expect(toggleEquipArmor(makeSlots(["dirt", 1]), empty, 0)).toBeNull();
  });

  test("unequipMissingArmor clears pieces that left the inventory", () => {
    const equipped = { ...createEmptyArmorEquipment(), helmet: "helmet", boots: "boots" };
    const slots = makeSlots(["helmet", 1]); // boots gone
    const next = unequipMissingArmor(slots, equipped)!;
    expect(next.helmet).toBe("helmet");
    expect(next.boots).toBeNull();
    expect(unequipMissingArmor(slots, next)).toBeNull(); // already consistent
  });

  test("armorReduction is 5% per defense point, capped, and requires owned pieces", () => {
    const slots = makeSlots(["helmet", 1], ["chestplate", 1]);
    const equipped = { ...createEmptyArmorEquipment(), helmet: "helmet", chestplate: "chestplate" };
    expect(armorReduction(slots, equipped)).toBeCloseTo((2 + 4) * 0.05);
    // Equipped but not owned counts for nothing.
    expect(armorReduction(makeSlots(["helmet", 1]), equipped)).toBeCloseTo(2 * 0.05);
    expect(armorReduction(slots, createEmptyArmorEquipment())).toBe(0);
  });

  test("equippedDefense sums defense points of owned equipped pieces", () => {
    const slots = makeSlots(["helmet", 1], ["chestplate", 1]);
    const equipped = { ...createEmptyArmorEquipment(), helmet: "helmet", chestplate: "chestplate" };
    expect(equippedDefense(slots, equipped)).toBe(2 + 4);
    expect(equippedDefense(makeSlots(["helmet", 1]), equipped)).toBe(2);
    expect(equippedDefense(slots, createEmptyArmorEquipment())).toBe(0);
  });
});

